// Initialize form data based on popup arguments
const productData = context.component?.props?.['productData'];
const isEdit = context.component?.props?.['isEdit'];

if (isEdit && productData) {
  // Copy product data to form
  context.component.variables['formProduct'] = {
    name: productData.name || '',
    description: productData.description || '',
    price: productData.price || 0,
    unit: productData.unit || 'lb',
    quantity: productData.quantity || 0,
    images: productData.images || [],
    category: productData.category || '',
    availableNow: productData.availableNow !== undefined ? productData.availableNow : true,
    nextAvailableDate: productData.nextAvailableDate || null,
    acceptsTrade: productData.acceptsTrade || false,
    acceptsCredit: productData.acceptsCredit || false
  };
} else {
  // Reset to default values for new product
  context.component.variables['formProduct'] = {
    name: '',
    description: '',
    price: 0,
    unit: 'lb',
    quantity: 0,
    images: [],
    category: '',
    availableNow: true,
    nextAvailableDate: null,
    acceptsTrade: false,
    acceptsCredit: false
  };
}

// Clear any existing errors
context.component.variables['formErrors'] = {
  name: '',
  price: '',
  quantity: '',
  category: ''
};

// Reset submitting state
context.component.variables['isSubmitting'] = false;
